    [155] = {
        name = "Arathi Basin Veteran",
        acquisition = "Difficulty: Hard - The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.\n\n1. Queue for a regular Arathi Basin match through the PvP interface. Track the achievement before the gates open; assault and defend are different actions recorded on the scoreboard.\n\n2. Win matches by holding bases, protecting flag channels and calling incoming enemies. Stay through each result so its victory is recorded.\n\n3. Repeat until the achievement counter reaches 100 victories. Losses and personal flag caps do not count as wins. Track the live counter on the character you are using rather than assuming old account statistics match it.",
        source = "Arathi Basin Veteran",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=155#comments",
        achievementId = 155,
        category = "PvP",
        stepCount = 3,
        waypoints = {},
