    [637] = {
        name = "Scarlet Monastery",
        acquisition = "Difficulty: Easy - Follow the legacy dungeon or raid route; the required boss kills are straightforward at current max level.\n\n1. Go to the monastery complex at 82.5, 33.0 in Tirisfal Glades. In the courtyard, choose the current Scarlet Monastery portal. Scarlet Halls and the restored old Library/Armory are different destinations.\n\n2. Clear Thalnos the Soulrender and Brother Korloff, then enter the cathedral and defeat Commander Durand to begin the last encounter.\n\n3. Fight High Inquisitor Whitemane, let her resurrection sequence complete, and finish both Whitemane and the revived Durand. Check credit after the encounter finishes; the old five-boss/four-wing circuit is no longer the requirement.",
        source = "Scarlet Monastery",
