    [639] = {
        name = "Zul'Farrak",
        acquisition = "Difficulty: Easy - Follow the legacy dungeon or raid route; the required boss kills are straightforward at current max level.\n\n1. Enter Zul'Farrak at 39.2, 21.6 in northwestern Tanaris on Normal difficulty.\n\n2. Reach the pyramid, kill the troll at the top and open the prisoners' cages. Protect Weegli Blastfuse through the staircase waves and defeat Shadowpriest Sezz'ziz.\n\n3. After the event, speak to Weegli and ask him to blow open the gate to the chief. Let him finish. Do not turn the prisoners hostile and kill the goblin before the gate opens.\n\n4. Pass through the opened gate and defeat Chief Ukorz Sandscalp. Gahz'rilla and the old Mallet of Zul'Farrak are not requirements for this achievement.",
        source = "Zul'Farrak",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=639#comments",
        achievementId = 639,
        category = "Dungeons",
        stepCount = 4,
        waypoints = {
