    [706] = {
        name = "Frostwolf Howler",
        acquisition = "Difficulty: Medium - Earn PvP currency and buy the correct faction mount; no rare drop is required.\n\nDifficulty: Medium - Earn 15 Marks of Honor and buy the faction mount; the original PvP rank and reputation requirements are no longer needed.\n\n1. Use an eligible Horde character and gather 15 Mark of Honor items. These are the account-bound items awarded by PvP reward boxes, not your Honor currency total or old battleground-specific tokens.\n\n2. Earn Marks through battleground PvP rewards. At the current PvP vendor, you can also exchange 2,000 Honor for an Orboreal Distinguishment containing 5 Marks, if offered; three boxes provide the 15 Marks for one mount. Transfer your Marks to the buyer before traveling.\n\n3. Visit Jorek Ironside in Hillsbrad Foothills, north of Tarren Mill (58.0, 33.4). Buy Horn of the Frostwolf Howler for 15 Marks of Honor. No city Exalted reputation, old PvP rank, or Alterac Valley reputation grind is required.\n\n4. Use Horn of the Frostwolf Howler to learn Frostwolf Howler. Search Collections > Mounts to confirm it was added. The purchase unlock is account-wide for characters eligible to use the mount.\n\n5. After learning the exact mount, check Frostwolf Howler in Achievements. A similarly named mount or merely killing the former drop boss does not satisfy this record.",
        source = "Jorek Ironside - Hillsbrad Foothills, north of Tarren Mill",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=706#comments",
        achievementId = 706,
        category = "Collections",
        stepCount = 5,
        waypoints = { { mapID = 25, x = 0.58, y = 0.334, step = 3, label = "Jorek Ironside - Horn of the Frostwolf Howler" } },
        sources = {
            "https://www.wowhead.com/achievement=706#comments:id=1004109",
            "https://www.wowhead.com/item=19029/horn-of-the-frostwolf-howler",
        },
        tips = "The price is 15 Mark of Honor items. Comments quoting 2,000 Honor, 50 AV tokens, 30 of each battleground token, or Rank 11 describe old systems.",
        reviewedAt = "2026-11-03",
        wowheadUrl = "https://www.wowhead.com/achievement=706",
        cost = "15 Mark of Honor",
        requirements = "Horde; Apprentice Riding; 15 Mark of Honor",
        faction = "horde",
        difficultyReason = "Earn PvP currency and buy the correct faction mount; no rare drop is required.",
        difficulty = "medium",
    },
    [707] = {
        name = "Stormpike Battle Charger",
        acquisition = "Difficulty: Medium - Earn PvP currency and buy the correct faction mount; no rare drop is required.\n\nDifficulty: Medium - Earn 15 Marks of Honor and buy the faction mount; the original PvP rank and reputation requirements are no longer needed.\n\n1. Use an eligible Alliance character and gather 15 Mark of Honor items. These are the account-bound items awarded by PvP reward boxes, not your Honor currency total or old battleground-specific tokens.\n\n2. Earn Marks through battleground PvP rewards. At the current PvP vendor, you can also exchange 2,000 Honor for an Orboreal Distinguishment containing 5 Marks, if offered; three boxes provide the 15 Marks for one mount. Transfer your Marks to the buyer before traveling.\n\n3. Visit Thanthaldis Snowgleam in Hillsbrad Foothills, The Headland (44.6, 46.0). Buy Stormpike Battle Charger for 15 Marks of Honor. No city Exalted reputation, old PvP rank, or Alterac Valley reputation grind is required.\n\n4. Use Stormpike Battle Charger to learn Stormpike Battle Charger. Search Collections > Mounts to confirm it was added. The purchase unlock is account-wide for characters eligible to use the mount.\n\n5. After learning the exact mount, check Stormpike Battle Charger in Achievements. A similarly named mount or merely killing the former drop boss does not satisfy this record.",
