    [708] = {
        name = "Hero of the Frostwolf Clan",
        acquisition = "Difficulty: Hard - Exalted battleground reputation requires a substantial number of objective-focused matches.\n\n1. Use a Horde character and track Frostwolf Clan in the reputation panel. Queue for Alterac Valley; buying its PvP mount does not grant this reputation achievement.\n\n2. Help complete the battleground's reputation-granting objectives: defeat enemy NPCs, burn enemy towers and contribute to victories. Loot enemies and use available battleground turn-ins while working on the other Alterac achievements.\n\n3. Repeat until the actual Frostwolf Clan reputation bar reaches EXALTED. A 100-win achievement, Honor level or city reputation is a different counter.",
        source = "Hero of the Frostwolf Clan",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=708#comments",
        achievementId = 708,
        category = "PvP",
