    [710] = {
        name = "The Defiler",
        acquisition = "Difficulty: Hard - Exalted battleground reputation requires a substantial number of objective-focused matches.\n\n1. Use a Horde character and track The Defilers in the reputation panel. Queue for Arathi Basin and concentrate on your team's resource income.\n\n2. Capture bases, leave defenders and reinforce attacks before flags are lost. Reputation is earned as your TEAM generates resources; you do not need to personally click every flag, and a loss can still yield progress.\n\n3. Keep playing until The Defilers reaches EXALTED. Check the reputation gained in your actual matches rather than using old comments' 2000-point formulas, removed guild perks or fixed hundreds-of-wins estimates.",
        source = "The Defiler",
        sourceType = "Achievement",
