    [712] = {
        name = "Warsong Outrider",
        acquisition = "Difficulty: Hard - Exalted battleground reputation requires a substantial number of objective-focused matches.\n\n1. Use a Horde character and track Warsong Outriders in the reputation panel. Queue for Warsong Gulch with teammates willing to carry and recover flags.\n\n2. Help your TEAM capture the enemy flag: escort its carrier and recover your own flag so the carrier can score. Your team's captures give reputation; midfield kills without captures are not an efficient reputation route.\n\n3. When Warsong Scramble is offered, its multiple flags and higher capture limit provide another documented reputation route. That does not mean the brawl qualifies for Quick Cap or Ironman.\n\n4. Repeat until Warsong Outriders reaches EXALTED. Old calculations assuming only 35 reputation per capture predate later increases; use the actual bar and gains shown on your character.",
        source = "Warsong Outrider",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=712#comments",
        achievementId = 712,
        category = "PvP",
