    [731] = {
        name = "Professional Expert",
        acquisition = "Difficulty: Medium - Higher Classic skill requires more materials, recipe progression or repeated practice.\n\n1. Choose a primary profession. In Stormwind or Orgrimmar, ask a city guard for that profession's trainer and follow the guard's marker to learn its CLASSIC skill. Cooking, Fishing and an expansion-specific profession category are not substitutes for a primary Classic profession.\n\n2. Open that profession's Classic category. Craft orange/yellow recipes, or gather Classic herbs, ore or skins with the corresponding gathering profession, until its base Classic skill reaches 225.\n\n3. Learn higher recipes or move to appropriate Classic materials as your current actions turn gray. Verify the achievement when the base skill reaches the target; racial or equipment bonuses may display extra skill without satisfying the earned-points requirement.",
        source = "Professional Expert",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=731#comments",
        achievementId = 731,
        category = "Professions",
        stepCount = 3,
        waypoints = {},
        sources = { "https://www.wowhead.com/achievement=731#comments:id=1375908" },
        tips = "The map menu includes the two main capitals. Ask a guard for the profession you chose; trainer locations and required materials depend on that choice.",
        reviewedAt = "2026-11-03",
        wowheadUrl = "https://www.wowhead.com/achievement=731",
        areaMaps = { 84, 85 },
        difficultyReason = "Higher Classic skill requires more materials, recipe progression or repeated practice.",
        difficulty = "medium",
    },
