            {
                mapID = 33,
                x = 0.542,
                y = 0.833,
                step = 3,
                label = "Lothos Riftwaker - Molten Core access",
                mapName = "Blackrock Mountain - lower approach",
            },
            { mapID = 232, x = 0.5623, y = 0.534, step = 3, label = "Ragnaros - original Molten Core" },
        },
        sources = {
            "https://www.wowhead.com/achievement=955#comments:id=2473761",
            "https://www.wowhead.com/achievement=955#comments:id=3245992",
            "https://www.wowhead.com/achievement=955#comments:id=5321031",
            "https://www.wowhead.com/achievement=955#comments:id=6385199",
            "https://www.wowhead.com/item=224561/commendation-of-the-hydraxian-waterlords",
            "https://www.wowhead.com/npc=234555/bobadormu",
        },
        tips = "The badge route is a current alternative to the long weekly grind. Classic Timewalking's quest/kill bonus does not automatically multiply reputation from commendation items. Use actual item gains and current buffs, not old Human racial or guild-perk calculations.",
        reviewedAt = "2026-11-03",
        wowheadUrl = "https://www.wowhead.com/achievement=955",
        difficultyReason = "Complete the quest or reputation route, using event currency where available.",
        difficulty = "medium",
