    [1151] = {
        name = "Loyal Defender",
        acquisition = "Difficulty: Hard - The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.\n\n1. Queue for Alterac Valley through the PvP interface's Epic Battlegrounds or available specific queue. Track the achievement inside the battleground; the outdoor Alterac caves are not where its objectives happen.\n\n2. Defend the Hall of the Stormpike, the room containing Vanndar Stormpike. Enemy players must actually enter that room; kills in the courtyard, bridge or outside keep do not satisfy the location.\n\n3. Help defeat intruders while staying near the fight. Use control to keep victims inside the hall, and receive the honorable kills. Do not just stand inside and attack targets who remain outside.\n\n4. Repeat until 50 qualifying player kills have credited across matches. Follow the live achievement counter; NPC boss deaths and kills elsewhere are not hall-defense credit.",
        source = "Loyal Defender",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=1151#comments",
        achievementId = 1151,
        category = "PvP",
        stepCount = 4,
        waypoints = {},
        sources = {
            "https://www.wowhead.com/achievement=1151#comments:id=435241",
            "https://www.wowhead.com/achievement=1151#comments:id=620150",
        },
        reviewedAt = "2026-11-03",
        wowheadUrl = "https://www.wowhead.com/achievement=1151",
        areaMaps = { 91 },
        difficultyReason = "The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.",
        difficulty = "hard",
    },
    [1153] = {
        name = "Overly Defensive",
        acquisition = "Difficulty: Hard - The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.\n\n1. Queue for a regular Arathi Basin match through the PvP interface. Track the achievement before the gates open; assault and defend are different actions recorded on the scoreboard.\n\n2. Watch the map for a flag your team owned that the enemy has just assaulted. Reach it during the contested timer, clear/control the attackers and personally channel the recapture.\n\n3. The flag must instantly return to your team for a defense. A neutral opening flag or fully enemy-owned flag is an assault. Finish THREE defenses in the SAME match; partial progress does not carry into the next battle.",
        source = "Overly Defensive",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=1153#comments",
        achievementId = 1153,
        category = "PvP",
