        areaMaps = { 91 },
        difficultyReason = "The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.",
        difficulty = "hard",
    },
    [1166] = {
        name = "To the Looter Go the Spoils",
        acquisition = "Difficulty: Hard - The objective depends on tight timing, an unusual match situation, coordinated team control or many victories.\n\n1. Queue for Alterac Valley through the PvP interface's Epic Battlegrounds or available specific queue. Track the achievement inside the battleground; the outdoor Alterac caves are not where its objectives happen.\n\n2. Help fight enemy players, then loot their corpses/take their insignias before someone else does. Keep a free bag slot so a gray-quality drop is not left behind.\n\n3. Continue looting until you personally obtain the Autographed Picture of Tigule. It is a random drop; defending your general's hall can provide corpses while also working on Loyal Defender.\n\n4. Loot it directly from a corpse for the achievement. Buying a picture at the Auction House, trading it, mailing it or unwrapping it does not satisfy the looting criterion.",
        source = "To the Looter Go the Spoils",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=1166#comments",
