    [1251] = {
        name = "Not In My House",
        acquisition = "Difficulty: Medium - Ordinary battleground objectives or cumulative counters require several matches and active participation.\n\n1. Queue for regular Warsong Gulch and track this achievement before the gates open. The map shows Warsong Gulch itself; Twin Peaks and other flag battlegrounds are different matches.\n\n2. Defend your team's Silverwing flag room with a small group. When an enemy picks up your flag, slow/stun them and focus their healer so they cannot escape.\n\n3. Receive credit for TWO enemy flag carriers killed before they leave that flag room, in ONE match. Keep the victims on the room's actual floor; the adjacent tunnel and side passage do not count as being inside.",
        source = "Not In My House",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=1251#comments",
        achievementId = 1251,
        category = "PvP",
        stepCount = 3,
        waypoints = {},
        sources = { "https://www.wowhead.com/achievement=1251#comments:id=646529" },
        tips = "The old ten-kill requirement was reduced to two. Follow the current criterion rather than old screenshots.",
        reviewedAt = "2026-11-03",
        wowheadUrl = "https://www.wowhead.com/achievement=1251",
        areaMaps = { 1339 },
        difficultyReason = "Ordinary battleground objectives or cumulative counters require several matches and active participation.",
        difficulty = "medium",
    },
    [1252] = {
        name = "Supreme Defender",
        acquisition = "Difficulty: Medium - Ordinary battleground objectives or cumulative counters require several matches and active participation.\n\n1. Queue for regular Warsong Gulch and track this achievement before the gates open. The map shows Warsong Gulch itself; Twin Peaks and other flag battlegrounds are different matches.\n\n2. Find the enemy carrying your team's flag, call their route and help your team defeat them. Stay in range to receive the honorable kill.\n\n3. Repeat until the achievement records 100 enemy flag-carrier kills. You do not need every killing blow. Returning the dropped flag can also advance Persistent Defender, but returns and carrier kills are separate counters.",
        source = "Supreme Defender",
        sourceType = "Achievement",
        sourceURL = "https://www.wowhead.com/achievement=1252#comments",
        achievementId = 1252,
        category = "PvP",
